//! strncpy, strncat, strncmp — bounded copy, padding, and truncation.

c_run_cases! {
    strncpy_copies_exactly_n_without_auto_null => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[8]; strncpy(d, \"planet\", 6); printf(\"%c%c%c%c%c%c\\n\", d[0],d[1],d[2],d[3],d[4],d[5]); return 0;", expect: ["planet"] },
    strncpy_truncates_long_source_at_n => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[5]; strncpy(d, \"galaxy\", 4); printf(\"%c%c%c%c\\n\", d[0],d[1],d[2],d[3]); return 0;", expect: ["gala"] },
    strncpy_n_zero_leaves_dest_bytes => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[4] = {'p','q','r','s'};", body: "strncpy(d, \"zzz\", 0); printf(\"%c%c\\n\", d[0], d[1]); return 0;", expect: ["pq"] },
    strncpy_pads_short_source_with_nulls => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[6]; memset(d, 'X', 6); strncpy(d, \"go\", 5); printf(\"%d %d %d\\n\", d[2]==0, d[3]==0, d[4]==0); return 0;", expect: ["1 1 1"] },
    strncpy_padding_byte_after_short_copy => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[5]; memset(d, '#', 5); strncpy(d, \"a\", 4); printf(\"%d\\n\", d[3]==0); return 0;", expect: ["1"] },
    strncpy_overwrites_prior_dest_contents => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[8] = \"rubbish\";", body: "strncpy(d, \"vy\", 3); d[2]='\\0'; printf(\"%s\\n\", d); return 0;", expect: ["vy"] },
    strncpy_from_empty_source_zeroes_first_n => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[4]; memset(d, '9', 4); strncpy(d, \"\", 3); printf(\"%d %d\\n\", d[0]==0, d[1]==0); return 0;", expect: ["1 1"] },
    strncpy_single_byte_copy => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[4] = \"old\";", body: "strncpy(d, \"newday\", 1); d[1]='\\0'; printf(\"%s\\n\", d); return 0;", expect: ["n"] },
    strncpy_return_value_points_to_dest => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[6]; char *r = strncpy(d, \"abc\", 3); printf(\"%d\\n\", r==d); return 0;", expect: ["1"] },
    strncpy_exact_length_source_no_extra_null => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[4]; strncpy(d, \"abc\", 3); printf(\"%c%c%c\\n\", d[0],d[1],d[2]); return 0;", expect: ["abc"] },
    strncpy_n_one_from_multi_char => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[3]; strncpy(d, \"zebra\", 1); d[1]='\\0'; printf(\"%s\\n\", d); return 0;", expect: ["z"] },
    strncpy_preserves_trailing_dest_when_n_shorter => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[6] = \"abcdef\";", body: "strncpy(d, \"12\", 2); printf(\"%c\\n\", d[5]); return 0;", expect: ["f"] },
    strncpy_two_char_source_into_five_slot => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[6]; memset(d, '?', 6); strncpy(d, \"xy\", 5); d[5]='\\0'; printf(\"%s\\n\", d); return 0;", expect: ["xy"] },
    strncpy_embedded_space_preserved => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[8]; strncpy(d, \"a b\", 3); d[3]='\\0'; printf(\"%s\\n\", d); return 0;", expect: ["a b"] },
    strncpy_digit_string_partial => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[5]; strncpy(d, \"12345\", 3); d[3]='\\0'; printf(\"%s\\n\", d); return 0;", expect: ["123"] },
    strncpy_uppercase_prefix_only => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "char d[6]; strncpy(d, \"HELLO\", 2); d[2]='\\0'; printf(\"%s\\n\", d); return 0;", expect: ["HE"] },
    strncat_appends_limited_suffix => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[16] = \"foo\";", body: "strncat(d, \"barbaz\", 3); printf(\"%s\\n\", d); return 0;", expect: ["foobar"] },
    strncat_zero_count_appends_nothing => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[12] = \"keep\";", body: "strncat(d, \"lose\", 0); printf(\"%s\\n\", d); return 0;", expect: ["keep"] },
    strncat_to_empty_dest => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[8] = \"\";", body: "strncat(d, \"seed\", 4); printf(\"%s\\n\", d); return 0;", expect: ["seed"] },
    strncat_n_exceeds_source_appends_all => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[12] = \"a\";", body: "strncat(d, \"bc\", 5); printf(\"%s\\n\", d); return 0;", expect: ["abc"] },
    strncat_single_char_append => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[8] = \"x\";", body: "strncat(d, \"yz\", 1); printf(\"%s\\n\", d); return 0;", expect: ["xy"] },
    strncat_return_value_is_dest => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[10] = \"m\";", body: "char *r = strncat(d, \"nop\", 2); printf(\"%d\\n\", r==d); return 0;", expect: ["1"] },
    strncat_preserves_middle_of_dest => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[16] = \"ab---\";", body: "strncat(d, \"cd\", 2); printf(\"%s\\n\", d); return 0;", expect: ["ab---cd"] },
    strncat_from_empty_source => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[8] = \"hi\";", body: "strncat(d, \"\", 3); printf(\"%s\\n\", d); return 0;", expect: ["hi"] },
    strncat_two_chars_from_long_suffix => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[12] = \"q\";", body: "strncat(d, \"werty\", 2); printf(\"%s\\n\", d); return 0;", expect: ["qwe"] },
    strncat_after_strncpy_null_terminated => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[12];", body: "strncpy(d, \"pre\", 4); strncat(d, \"fix\", 3); printf(\"%s\\n\", d); return 0;", expect: ["prefix"] },
    strncat_digit_suffix => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[10] = \"id\";", body: "strncat(d, \"1234\", 2); printf(\"%s\\n\", d); return 0;", expect: ["id12"] },
    strncat_space_in_suffix => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[14] = \"say\";", body: "strncat(d, \" hi\", 3); printf(\"%s\\n\", d); return 0;", expect: ["say hi"] },
    strncat_three_way_chain => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[20] = \"a\";", body: "strncat(d, \"b\", 1); strncat(d, \"c\", 1); printf(\"%s\\n\", d); return 0;", expect: ["abc"] },
    strncat_uppercase_chunk => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[12] = \"mix\";", body: "strncat(d, \"ED\", 2); printf(\"%s\\n\", d); return 0;", expect: ["mixED"] },
    strncat_partial_append_length => { includes: ["<stdio.h>", "<string.h>"], decls: "char d[16] = \"start\";", body: "strncat(d, \"end\", 3); printf(\"%d\\n\", (int)strlen(d)); return 0;", expect: ["8"] },
    strncmp_equal_within_n => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"kite\", \"kite\", 4)); return 0;", expect: ["0"] },
    strncmp_equal_prefix_only_n => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"kite\", \"kind\", 2)); return 0;", expect: ["0"] },
    strncmp_less_at_third_char => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"apple\", \"apply\", 5) < 0); return 0;", expect: ["1"] },
    strncmp_greater_at_first_char => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"dog\", \"cat\", 3) > 0); return 0;", expect: ["1"] },
    strncmp_n_zero_always_equal => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"any\", \"other\", 0)); return 0;", expect: ["0"] },
    strncmp_empty_vs_empty => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"\", \"\", 0)); return 0;", expect: ["0"] },
    strncmp_empty_less_than_char => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"\", \"a\", 1) < 0); return 0;", expect: ["1"] },
    strncmp_char_greater_than_empty => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"z\", \"\", 1) > 0); return 0;", expect: ["1"] },
    strncmp_case_sensitive_mismatch => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"Ab\", \"ab\", 2) != 0); return 0;", expect: ["1"] },
    strncmp_diff_after_n_ignored => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"abcX\", \"abcY\", 3)); return 0;", expect: ["0"] },
    strncmp_first_byte_diff => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"1\", \"2\", 1) < 0); return 0;", expect: ["1"] },
    strncmp_digit_strings_lexicographic => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"10\", \"2\", 2) < 0); return 0;", expect: ["1"] },
    strncmp_shorter_n_stops_early => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"abcdef\", \"abczzz\", 3)); return 0;", expect: ["0"] },
    strncmp_n_equals_one => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"moon\", \"noon\", 1)); return 0;", expect: ["-1"] },
    strncmp_identical_one_char => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\"q\", \"q\", 1)); return 0;", expect: ["0"] },
    strncmp_space_vs_letter => { includes: ["<stdio.h>", "<string.h>"], decls: "", body: "printf(\"%d\\n\", strncmp(\" a\", \"!a\", 2) > 0); return 0;", expect: ["0"] },
}
